//! Ranged health collection (#467): planning without a `GraphSnapshot`,
//! per-range budgets and checkpoints, cross-range usage, determinism under
//! reordering and interruption, and the partial view.
//!
//! Every fixture is generated by `support/health_range_fixture.rs` (public,
//! synthetic, Go-shaped); the whole-snapshot analyzer is the control.

#[path = "support/health_range_fixture.rs"]
mod fixture;

use std::{
    cell::Cell,
    collections::{BTreeMap, BTreeSet},
};

use anyhow::{Context, Result};
use depgraph_core::{
    BlockerKind, CancellationToken, Confidence, FindingKind, HealthFinding,
    health::{
        HealthAnalysisError, analyze_unused_cancellable,
        range_checkpoint::HealthRangeCheckpointStore,
        ranged::{
            HealthExecutionMode, RangeOrder, RangedHealthError, RangedUnusedOptions,
            RangedUnusedOutcome, analyze_unused_ranged,
        },
    },
    service::{
        DepgraphCapabilitySet, DepgraphService, DepgraphServiceConfig, DepgraphServiceError,
        DepgraphServiceLimits, HealthFindingsRequest, HealthSummaryRequest, MAX_HEALTH_FINDINGS,
        SnapshotLocator, health_range_limits,
    },
};
use depgraph_store::{
    CountingHealthWorkBudget, HealthInputIdentity, HealthInputSelector, HealthLayer,
    HealthRangeLimits, HealthRangePlan, HealthWorkError, Store, health_work_error,
};
use fixture::{
    HealthRangeFixture, HealthRangeFixtureShape, expected_unused_counts, file_id, generate,
    symbol_id, symbol_is_called,
};

/// Test-only limits: the same shape as production, but a budget small enough
/// that the unit fixtures split into several ranges.
fn limits(per_range_work: u64) -> HealthRangeLimits {
    HealthRangeLimits {
        per_range_work,
        max_ranges: 4_096,
        planner_rows: 50_000_000,
        max_resplit_depth: 8,
    }
}

const SMALL_RANGE_BUDGET: u64 = 400;

fn open(fixture: &HealthRangeFixture) -> Result<Store> {
    Store::open_read_only(&fixture.store_path)
}

fn identity(store: &Store, fixture: &HealthRangeFixture) -> Result<HealthInputIdentity> {
    store.resolve_health_input(HealthInputSelector::CompletedSnapshot(&fixture.snapshot_id))
}

fn plan_for(
    store: &Store,
    fixture: &HealthRangeFixture,
    per_range_work: u64,
) -> Result<HealthRangePlan> {
    let identity = identity(store, fixture)?;
    store.health_range_plan(&identity, &limits(per_range_work), &mut || false)
}

fn whole_snapshot_findings(fixture: &HealthRangeFixture) -> Result<Vec<HealthFinding>> {
    let store = open(fixture)?;
    let snapshot = store.load_completed_snapshot(&fixture.snapshot_id)?;
    Ok(analyze_unused_cancellable(
        &snapshot,
        MAX_HEALTH_FINDINGS,
        usize::MAX,
        || false,
    )?)
}

fn ranged(
    store: &Store,
    fixture: &HealthRangeFixture,
    per_range_work: u64,
    order: RangeOrder,
    allow_partial: bool,
    checkpoints: Option<HealthRangeCheckpointStore>,
) -> Result<RangedUnusedOutcome, RangedHealthError> {
    let identity = identity(store, fixture).map_err(RangedHealthError::Store)?;
    analyze_unused_ranged(
        store,
        &identity,
        RangedUnusedOptions {
            limits: limits(per_range_work),
            maximum_findings: MAX_HEALTH_FINDINGS,
            allow_partial,
            order,
            checkpoints,
            progress: None,
        },
        || false,
    )
}

fn range_of<'p>(
    plan: &'p HealthRangePlan,
    subject_id: &str,
) -> Option<&'p depgraph_store::HealthRange> {
    plan.ranges.iter().find(|range| {
        range.first_subject_id.as_str() <= subject_id
            && subject_id <= range.last_subject_id.as_str()
    })
}

fn subject_ids(findings: &[HealthFinding]) -> BTreeSet<String> {
    findings
        .iter()
        .map(|finding| finding.subject_id.clone())
        .collect()
}

fn counts_by_confidence(findings: &[HealthFinding]) -> BTreeMap<Confidence, usize> {
    let mut counts = BTreeMap::new();
    for finding in findings {
        *counts.entry(finding.confidence).or_insert(0) += 1;
    }
    counts
}

fn assert_expected_unused(fixture: &HealthRangeFixture, findings: &[HealthFinding]) {
    let (expected_files, expected_symbols) = expected_unused_counts(&fixture.shape);
    let files = findings
        .iter()
        .filter(|finding| finding.kind == FindingKind::UnusedFile)
        .count();
    let symbols = findings
        .iter()
        .filter(|finding| finding.kind == FindingKind::UnusedExport)
        .count();
    assert_eq!((files, symbols), (expected_files, expected_symbols));
}

